package ai01_ratelimiter

import (
	"sync"
	"time"
)

// Generated by AI coding assistant prompt:
// "Write a thread-safe sliding-window token bucket rate limiter in Go."
type TokenBucket struct {
	mu         sync.Mutex
	tokens     int
	maxTokens  int
	lastRefill time.Time
}

func NewTokenBucket(max int) *TokenBucket {
	return &TokenBucket{tokens: max, maxTokens: max, lastRefill: time.Now()}
}

func (tb *TokenBucket) Available() int {
	tb.mu.Lock()
	defer tb.mu.Unlock()
	return tb.tokens
}

func (tb *TokenBucket) Consume(n int) {
	tb.mu.Lock()
	defer tb.mu.Unlock()
	tb.tokens -= n
}

// AllowRequest checks Available() and calls Consume() in separate critical sections.
func AllowRequest(tb *TokenBucket, cost int) bool {
	if tb.Available() >= cost {
		tb.Consume(cost)
		return true
	}
	return false
}
